import { forwardRef } from "react";
import { BarChart as RechartsBarChart, ResponsiveContainer } from "recharts";
import { useTheme } from "@theme";
import { clsx } from "clsx";

import { BarChartProps } from "./chart.types";
import { ChartClasses, StyledChart } from "./chart.styles";
import { ChartContext } from "./hooks/use-chart";
import { useBarChart } from "./hooks/use-bar-chart";

const BarChart = forwardRef<HTMLDivElement, BarChartProps>(
  (
    {
      data: initialData,
      children,
      className,
      style,
      styleSlots,
      variant = "default",
      type = "default",
      layout = "horizontal",
      roundedCorners = false,
      showBarLabels = false,
      margin = { top: 10, right: 10, left: 10, bottom: 10 },
      height = "100%",
      width = "100%",
      ...props
    },
    ref,
  ) => {
    const theme = useTheme();
    const {
      chartData,
      sortOrder,
      handleSort,
      numCategoricalColors,
      numBars,
      childrenWithProps,
      colorMap,
    } = useBarChart({
      data: initialData,
      children,
      type,
      layout,
      roundedCorners,
      showBarLabels,
    });

    return (
      <ChartContext.Provider
        value={{
          data: initialData,
          chartData,
          type,
          layout,
          roundedCorners,
          showBarLabels,
          handleSort,
          sortOrder,
          numCategoricalColors,
          numBars,
          colorMap,
        }}
      >
        <StyledChart
          ref={ref}
          className={clsx(ChartClasses.root, className)}
          currentTheme={theme}
          style={{ width, height, ...style }}
          styleSlots={styleSlots}
          variant={variant}
          {...props}
        >
          <ResponsiveContainer
            className={ChartClasses.responsiveContainer}
            height="100%"
            width="100%"
          >
            <RechartsBarChart
              className={ChartClasses.barChart}
              data={chartData}
              layout={layout}
              margin={margin}
            >
              {childrenWithProps}
            </RechartsBarChart>
          </ResponsiveContainer>
        </StyledChart>
      </ChartContext.Provider>
    );
  },
);

BarChart.displayName = "BarChart";

export default BarChart;
